package com.apexstreet.service;

import com.apexstreet.dto.*; import com.apexstreet.model.*; import com.apexstreet.repository.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;

@Service @Transactional
public class AutomationService {
 private final AreaRepository areas; private final StreetLightRepository lights; private final AutomationConfigurationRepository configs; private final AutomationSchedulePhaseRepository phases; private final AutomationLightOverrideRepository overrides; private final AutomationEventPlanRepository events; private final ActivityLogService activityLogs;
 public AutomationService(AreaRepository a,StreetLightRepository l,AutomationConfigurationRepository c,AutomationSchedulePhaseRepository p,AutomationLightOverrideRepository o,AutomationEventPlanRepository e,ActivityLogService activityLogs){areas=a;lights=l;configs=c;phases=p;overrides=o;events=e;this.activityLogs=activityLogs;}
 private Area area(Long id){return areas.findById(id).orElseThrow(()->new AreaNotFoundException(id));}
 private AutomationConfiguration config(Area a){return configs.findByAreaId(a.getId()).orElseGet(()->{var c=new AutomationConfiguration();c.setArea(a);c.setEnabled(a.isAutomationEnabled());return configs.save(c);});}
 public List<AutomationResponses.AreaSummary> summaries(){return areas.findAll().stream().map(a->{var c=config(a);var ls=lights.findForArea(a,a.getName());return new AutomationResponses.AreaSummary(a.getId(),a.getName(),a.getType().name(),ls.size(),ls.stream().filter(x->x.isFaultStatus()||x.getStatus()==StreetLightStatus.FAULT).count(),c.isEnabled(),c.getMode());}).toList();}
 public AutomationResponses.Page page(Long id){Area a=area(id);var c=config(a);var active=activeOverrides(a);var byLight=new HashMap<Long,AutomationLightOverride>();active.forEach(o->byLight.put(o.getStreetLight().getId(),o));var ls=lights.findForArea(a,a.getName());var lightDtos=ls.stream().map(s->{var o=byLight.get(s.getId());return new AutomationResponses.Light(s.getLightId(),s.getId(),a.getName(),s.getStatus(),s.getMode(),o==null?AutomationOverrideMode.AUTO:o.getMode(),o==null?s.getBrightness():o.getBrightness(),s.isFaultStatus(),o==null?null:o.getExpiresAt());}).toList();var ps=phases.findByConfigurationIdOrderByWeekTypeAscPhaseOrderAsc(c.getId()).stream().map(p->new AutomationResponses.Phase(p.getId(),p.getStartTime(),p.getEndTime(),p.getAction(),p.getBrightness(),p.getWeekType(),p.getPriority(),p.getPhaseOrder())).toList();var es=events.findByAreaIdOrderByEventDateAsc(id).stream().map(e->new AutomationResponses.Event(e.getId(),e.getName(),e.getEventDate(),e.getBrightness(),e.isEnabled())).toList();var os=active.stream().map(o->new AutomationResponses.Light(o.getStreetLight().getLightId(),o.getStreetLight().getId(),a.getName(),o.getStreetLight().getStatus(),o.getStreetLight().getMode(),o.getMode(),o.getBrightness(),o.getStreetLight().isFaultStatus(),o.getExpiresAt())).toList();return new AutomationResponses.Page(id,a.getName(),a.getType().name(),c.isEnabled(),c.getMode(),c.getSeason(),c.isFaultHoldEnabled(),c.isPreserveLastSafeCommand(),ls.size(),ls.stream().filter(x->x.isFaultStatus()||x.getStatus()==StreetLightStatus.FAULT).count(),ps,lightDtos,es,os);}
 private List<AutomationLightOverride> activeOverrides(Area a){var now=LocalDateTime.now();var list=overrides.findByAreaIdAndStatus(a.getId(),AutomationOverrideStatus.ACTIVE);list.stream().filter(o->o.getExpiresAt()!=null&&o.getExpiresAt().isBefore(now)).forEach(o->{o.setStatus(AutomationOverrideStatus.EXPIRED);overrides.save(o);});return list.stream().filter(o->o.getStatus()==AutomationOverrideStatus.ACTIVE).toList();}
 public AutomationResponses.Page updateConfig(Long id,AutomationRequests.ConfigurationRequest r){var c=config(area(id));if(r.enabled()!=null)c.setEnabled(r.enabled());if(r.mode()!=null)c.setMode(r.mode());if(r.faultHoldEnabled()!=null)c.setFaultHoldEnabled(r.faultHoldEnabled());if(r.preserveLastSafeCommand()!=null)c.setPreserveLastSafeCommand(r.preserveLastSafeCommand());if(r.season()!=null)c.setSeason(r.season());c.getArea().setAutomationEnabled(c.isEnabled());if(c.isEnabled()){overrides.closeActive(id,AutomationOverrideStatus.CLEARED);lights.findForArea(c.getArea(),c.getArea().getName()).stream().filter(s->!s.isFaultStatus()&&s.getStatus()!=StreetLightStatus.FAULT).forEach(s->{s.setMode(StreetLightMode.AUTO);lights.save(s);});}activityLogs.record("Automation configuration updated","Updated automation configuration for "+c.getArea().getName(),"Automation",c.getArea().getName(),String.valueOf(id),"Success","User Action");return page(id);}
 public AutomationResponses.Page createPhase(Long id,AutomationRequests.PhaseRequest r){var c=config(area(id));var p=new AutomationSchedulePhase();p.setConfiguration(c);copy(p,r);phases.save(p);return page(id);}
 public AutomationResponses.Page updatePhase(Long id,Long phaseId,AutomationRequests.PhaseRequest r){var p=phases.findByIdAndConfigurationId(phaseId,config(area(id)).getId()).orElseThrow(()->new IllegalArgumentException("Schedule phase not found"));copy(p,r);return page(id);}
 private void copy(AutomationSchedulePhase p,AutomationRequests.PhaseRequest r){p.setStartTime(r.startTime());p.setEndTime(r.endTime());p.setAction(r.action());p.setBrightness(r.brightness());p.setWeekType(r.weekType());p.setPriority(r.priority()==null?0:r.priority());p.setPhaseOrder(r.phaseOrder()==null?0:r.phaseOrder());}
 public AutomationResponses.Page deletePhase(Long id,Long phaseId){phases.delete(phases.findByIdAndConfigurationId(phaseId,config(area(id)).getId()).orElseThrow(()->new IllegalArgumentException("Schedule phase not found")));return page(id);}
 public AutomationResponses.Page override(Long id,String lightId,AutomationRequests.OverrideRequest r){Area a=area(id);var s=lights.findForArea(a,a.getName()).stream().filter(x->x.getLightId().equals(lightId)).findFirst().orElseThrow(()->new IllegalArgumentException("Street light is not in this area"));if(r.mode()==AutomationOverrideMode.AUTO){return clearOverride(id,lightId);}var o=overrides.findByAreaIdAndStreetLightIdAndStatus(id,s.getId(),AutomationOverrideStatus.ACTIVE).orElseGet(AutomationLightOverride::new);o.setArea(a);o.setStreetLight(s);o.setMode(AutomationOverrideMode.MANUAL);o.setBrightness(r.brightness());o.setDurationMinutes(r.durationMinutes());o.setExpiresAt(r.durationMinutes()==null?null:LocalDateTime.now().plusMinutes(r.durationMinutes()));o.setStatus(AutomationOverrideStatus.ACTIVE);overrides.save(o);s.setBrightness(r.brightness());s.setStatus(r.brightness() == 0 ? StreetLightStatus.OFF : r.brightness() == 100 ? StreetLightStatus.ON : StreetLightStatus.DIM);s.setMode(StreetLightMode.MANUAL);lights.save(s);activityLogs.record("Manual light command", "Manually set " + s.getLightId() + " to " + s.getStatus(), "Automation", a.getName(), s.getLightId(), "Success", "User Action");return page(id);}
 public AutomationResponses.Page group(Long id,AutomationRequests.GroupCommandRequest r){Area a=area(id);var ls=lights.findForArea(a,a.getName());ls.forEach(s->{var o=overrides.findByAreaIdAndStreetLightIdAndStatus(id,s.getId(),AutomationOverrideStatus.ACTIVE).orElseGet(AutomationLightOverride::new);o.setArea(a);o.setStreetLight(s);o.setMode(r.mode());o.setBrightness(r.brightness());o.setDurationMinutes(r.durationMinutes());o.setExpiresAt(r.durationMinutes()==null?null:LocalDateTime.now().plusMinutes(r.durationMinutes()));o.setStatus(AutomationOverrideStatus.ACTIVE);overrides.save(o);});return page(id);}
 public AutomationResponses.Page returnToSchedule(Long id){overrides.closeActive(id,AutomationOverrideStatus.CLEARED);return page(id);}
 public AutomationResponses.Page clearOverride(Long id,String lightId){Area a=area(id);var s=lights.findForArea(a,a.getName()).stream().filter(x->x.getLightId().equals(lightId)).findFirst().orElseThrow(()->new IllegalArgumentException("Street light is not in this area"));overrides.findByAreaIdAndStreetLightIdAndStatus(id,s.getId(),AutomationOverrideStatus.ACTIVE).ifPresent(o->{o.setStatus(AutomationOverrideStatus.CLEARED);overrides.save(o);});s.setMode(StreetLightMode.AUTO);lights.save(s);activityLogs.record("Manual override cleared", "Returned " + s.getLightId() + " to its automation schedule", "Automation", a.getName(), s.getLightId(), "Success", "User Action");return page(id);}
 public AutomationResponses.Page createEvent(Long id,AutomationRequests.EventRequest r){var e=new AutomationEventPlan();e.setArea(area(id));copy(e,r);events.save(e);return page(id);}
 public AutomationResponses.Page updateEvent(Long id,Long eventId,AutomationRequests.EventRequest r){var e=events.findByIdAndAreaId(eventId,id).orElseThrow(()->new IllegalArgumentException("Event plan not found"));copy(e,r);return page(id);}
 private void copy(AutomationEventPlan e,AutomationRequests.EventRequest r){e.setName(r.name());e.setEventDate(r.eventDate());e.setBrightness(r.brightness());e.setEnabled(r.enabled()==null||r.enabled());}
 public AutomationResponses.Page deleteEvent(Long id,Long eventId){events.delete(events.findByIdAndAreaId(eventId,id).orElseThrow(()->new IllegalArgumentException("Event plan not found")));return page(id);}
}
